import logging
import os
import subprocess

from os.path import abspath
from ute_wtssim import ute_wtssim
from ..exception import ProcessNotFound


FORMAT = '%(asctime)s ::: %(levelname)-7s ::: %(message)s'
logging.basicConfig(format=FORMAT, datefmt='%H:%M:%S')
logger = logging.getLogger('ute_wtssim')
logger.setLevel(logging.INFO)


def start_egate_only(args):
    """ Brings an already configured egate to ACTIVE state. """
    wtssim = ute_wtssim()
    wtssim.setup_egate(alias="script", **vars(args))
    wtssim.start_egate_services(timeout=500, retry=args.retry,
                                check_version=args.check_version, alias="script")
    logger.info("Egate port: {}".format(args.egate_port))
    logger.info("UTE WTSSIM HAS ENDED.")


def configure_egate(args):
    """ Creates egate instance and brings it to a required state. """
    logger.info("UTE WTSSIM HAS STARTED.")
    args.cfg_file = abspath(args.cfg_file) if args.cfg_file else None
    args.suite_file = abspath(args.suite_file) if args.suite_file else None
    args.tool_dir = abspath(args.tool_dir) if args.tool_dir else None
    args.lua_dirs = ((abspath(ldir)) for ldir in args.lua_dirs)

    wtssim = ute_wtssim()

    if args.cfg_file is None and args.suite_file is None:
        logger.info("Using default configuration lua...")
        args.cfg_file = _get_default_config_file()

    logger.info("Starting WTS applications...")
    wtssim.start_wts_applications(timeout=100, alias='script', **vars(args))
    logger.info("WTS applications has been started on egate port {}.".format(args.egate_port))

    if args.state == "ACTIVE":
        logger.info("Starting WTS services...")
        wtssim.start_wts_services(retry=int(args.retry), timeout=500,
                                  check_version=args.check_version, alias='script')
    elif args.state == "CONFIGURED":
        logger.info("Skipping activation...")

    logger.info("WTS services on port {} is now {}.".format(args.egate_port, args.state))
    logger.info("Egate port: {}".format(args.egate_port))
    logger.info("Edaemon port/s: {}".format(str(args.edaemon_ports)))
    logger.info("UTE WTSSIM HAS ENDED.")


def _get_default_config_file():
    """ Return a path to the default configuration file. """
    here = os.path.dirname(__file__)
    egate_config_path = os.path.join(here, 'resources/egate_configuration.lua')
    return egate_config_path


def kill_egate_and_edaemon(args):
    """ Kills running egate and/or edaemon processes. """
    egate = subprocess.Popen(["pgrep", "-f", "./egate --port {}".format(args.egate)], stdout=subprocess.PIPE)
    for pid in egate.stdout:
        subprocess.Popen(["kill", "{}".format(int(pid))], stdout=subprocess.PIPE)
        logger.info("Egate process in port {} is terminated.".format(args.egate))
        break
    else:
        raise ProcessNotFound("Egate", args.egate, "Run 'configure' or 'start' first to initialize process.")

    for port in args.edaemon:
        edaemon = subprocess.Popen(["pgrep", "-f", "./edaemon --port {}".format(port)], stdout=subprocess.PIPE)
        for pid in edaemon.stdout:
            subprocess.Popen(["sudo", "kill", "{}".format(int(pid))], stdout=subprocess.PIPE)
            logger.info("Edaemon process in port {} is terminated.".format(port))
            break
        else:
            raise ProcessNotFound("Edaemon", args.edaemon, "Run 'configure' or 'start' first to initialize process.")
